//! WebAssembly module of the presentation site: the hero "dust" simulation and the
//! live SEO playground (powered by the `active` crate).
use wasm_bindgen::prelude::*;

/// Head tags for the playground, generated by the `active` crate.
#[wasm_bindgen]
pub fn seo_head(title: &str, description: &str, path: &str, origin: &str) -> String {
    let json_ld = format!(
        r#"{{"@context":"https://schema.org","@type":"WebPage","name":"{}","description":"{}"}}"#,
        json_escape(title),
        json_escape(description)
    );
    active::Seo::new()
        .site_name("Acme")
        .title_template("%s · Acme")
        .base_url(origin)
        .image("/og.png")
        .title(title)
        .description(description)
        .canonical(path)
        .json_ld(json_ld)
        .to_html()
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

/// The WebAssembly memory, so JavaScript can read particle positions without copying.
#[wasm_bindgen]
pub fn wasm_memory() -> JsValue {
    wasm_bindgen::memory()
}

/// Particles that gather into a shape ("home" points), drift with a soft noise,
/// flee the pointer and scatter when `scatter` goes from 0 to 1.
#[wasm_bindgen]
pub struct Dust {
    pos: Vec<f32>,
    vel: Vec<f32>,
    home: Vec<f32>,
    drift: Vec<f32>,
    stiffness: Vec<f32>,
    width: f32,
    height: f32,
    time: f32,
}

#[wasm_bindgen]
impl Dust {
    #[wasm_bindgen(constructor)]
    pub fn new(count: usize, width: f32, height: f32, seed: u32) -> Dust {
        let mut rng = Rng(seed | 1);
        let mut pos = Vec::with_capacity(count * 2);
        let mut drift = Vec::with_capacity(count * 2);
        let mut stiffness = Vec::with_capacity(count);
        for _ in 0..count {
            pos.push(rng.next() * width);
            pos.push(rng.next() * height);
            let angle = rng.next() * core::f32::consts::TAU;
            let reach = 0.25 + rng.next() * 0.75;
            drift.push(angle.cos() * reach);
            drift.push(angle.sin() * reach);
            stiffness.push(0.55 + rng.next() * 0.9);
        }
        Dust { home: pos.clone(), vel: vec![0.0; count * 2], pos, drift, stiffness, width, height, time: 0.0 }
    }

    pub fn count(&self) -> usize {
        self.stiffness.len()
    }

    pub fn resize(&mut self, width: f32, height: f32) {
        self.width = width;
        self.height = height;
    }

    /// Interleaved x, y target points; reused cyclically if there are fewer points than particles.
    pub fn set_home(&mut self, points: &[f32]) {
        let n = points.len() / 2;
        if n == 0 {
            return;
        }
        for i in 0..self.count() {
            let j = i % n;
            self.home[i * 2] = points[j * 2];
            self.home[i * 2 + 1] = points[j * 2 + 1];
        }
    }

    /// Advances the simulation by `dt` seconds. `(px, py)` is the pointer (NaN when absent).
    pub fn step(&mut self, dt: f32, px: f32, py: f32, scatter: f32) {
        let dt = dt.clamp(0.0, 1.0 / 30.0);
        self.time += dt;
        let t = self.time;
        let damping = (-3.6 * dt).exp();
        let radius = 110.0_f32;
        let pointer = !px.is_nan();
        let spread = self.width.max(self.height) * 0.9 * scatter * scatter;
        for i in 0..self.count() {
            let (ix, iy) = (i * 2, i * 2 + 1);
            let (x, y) = (self.pos[ix], self.pos[iy]);
            // Target: home point, blown away along a personal direction when scattering.
            let tx = self.home[ix] + self.drift[ix] * spread;
            let ty = self.home[iy] + self.drift[iy] * spread;
            let k = 7.0 * self.stiffness[i];
            let mut ax = (tx - x) * k;
            let mut ay = (ty - y) * k;
            // Soft wandering noise so the shape breathes.
            let phase = i as f32 * 0.37;
            ax += (y * 0.011 + t * 0.9 + phase).sin() * 26.0;
            ay += (x * 0.013 - t * 0.8 + phase).cos() * 26.0;
            if pointer {
                let (dx, dy) = (x - px, y - py);
                let d2 = dx * dx + dy * dy;
                if d2 < radius * radius && d2 > 0.01 {
                    let d = d2.sqrt();
                    let f = (1.0 - d / radius) * 5200.0;
                    ax += dx / d * f;
                    ay += dy / d * f;
                }
            }
            self.vel[ix] = (self.vel[ix] + ax * dt) * damping;
            self.vel[iy] = (self.vel[iy] + ay * dt) * damping;
            self.pos[ix] = x + self.vel[ix] * dt;
            self.pos[iy] = y + self.vel[iy] * dt;
        }
    }

    /// Pointer to `count() * 2` interleaved f32 positions inside `memory()`.
    pub fn positions(&self) -> *const f32 {
        self.pos.as_ptr()
    }
}

/// xorshift32 — tiny deterministic PRNG, values in [0, 1).
struct Rng(u32);
impl Rng {
    fn next(&mut self) -> f32 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 17;
        self.0 ^= self.0 << 5;
        (self.0 >> 8) as f32 / (1u32 << 24) as f32
    }
}
